function solid(c,o){const p={type:"SOLID",color:c}; if(o!==undefined)p.opacity=o; return p;}
function txt(chars, size, style, color){ const t=figma.createText(); t.fontName={family:"Roboto",style:style}; t.fontSize=size; t.characters=chars; t.fills=[solid(color)]; return t; }
function auto(dir, gap, pad){ const f=figma.createFrame(); f.layoutMode=dir; f.itemSpacing=gap; if(pad){f.paddingLeft=pad[0];f.paddingRight=pad[0];f.paddingTop=pad[1];f.paddingBottom=pad[1];} f.fills=[]; f.primaryAxisSizingMode="AUTO"; f.counterAxisSizingMode="AUTO"; return f; }
