const made = {};

// IconBtn: 44x44 circle, surface bg, border, centered 24 icon slot
function mkIconBtn(bg, border){
  const c = figma.createComponent(); c.resize(44,44); c.cornerRadius=22;
  c.fills=[solid(bg)]; c.strokes= border?[solid(border)]:[]; c.strokeWeight=1;
  c.layoutMode="HORIZONTAL"; c.primaryAxisAlignItems="CENTER"; c.counterAxisAlignItems="CENTER";
  c.primaryAxisSizingMode="FIXED"; c.counterAxisSizingMode="FIXED";
  return c;
}
made.iconBtnSurface = comp("IconBtn / Surface", mkIconBtn(C.SURF, C.BORDER));
made.iconBtnTint = comp("IconBtn / Tint", mkIconBtn(C.REDTINT, null));
made.iconBtnGhost = comp("IconBtn / Ghost", (()=>{const c=mkIconBtn(C.SURF,null); c.opacity=0.16; return c;})());

// CategoryChip
function mkChip(label, sel){
  const c = figma.createComponent(); c.layoutMode="HORIZONTAL"; c.primaryAxisSizingMode="AUTO"; c.counterAxisSizingMode="AUTO";
  c.paddingLeft=20;c.paddingRight=20;c.paddingTop=10;c.paddingBottom=10; c.cornerRadius=999;
  c.fills=[solid(sel?C.RED:C.SURF)]; c.strokes=[solid(sel?C.RED:C.BORDER)]; c.strokeWeight=1;
  const t=txt(label,14,sel?"Medium":"Regular",sel?C.WHITE:C.TEXT2); c.appendChild(t);
  return c;
}
made.chipSel = comp("Chip / Category=Selected", mkChip("All", true));
made.chipDef = comp("Chip / Category=Default", mkChip("Combos", false));

// SpiceChip
function mkSpice(label, sel){
  const c = figma.createComponent(); c.layoutMode="HORIZONTAL"; c.primaryAxisSizingMode="AUTO"; c.counterAxisSizingMode="AUTO";
  c.paddingLeft=18;c.paddingRight=18;c.paddingTop=9;c.paddingBottom=9; c.cornerRadius=999;
  c.fills=[solid(sel?C.RED:C.SURF)]; c.strokes=[solid(sel?C.RED:C.BORDER)]; c.strokeWeight=1;
  c.appendChild(txt(label,13,sel?"Medium":"Regular",sel?C.WHITE:C.TEXT2));
  return c;
}
made.spiceSel = comp("Chip / Spice=Selected", mkSpice("Mild", true));
