// StepperBtn
function mkStep(glyph, disabled){
  const c = figma.createComponent(); c.resize(40,40); c.cornerRadius=20;
  c.fills=[solid(disabled?C.BG:C.REDTINT)];
  c.layoutMode="HORIZONTAL"; c.primaryAxisAlignItems="CENTER"; c.counterAxisAlignItems="CENTER";
  c.primaryAxisSizingMode="FIXED"; c.counterAxisSizingMode="FIXED";
  const t=txt(glyph,20,"Medium", disabled?C.DISABLED:C.RED); c.appendChild(t);
  return c;
}
made.stepMinus = comp("Stepper / Minus", mkStep("–", false));
made.stepMinusDis = comp("Stepper / Minus=Disabled", mkStep("–", true));
made.stepPlus = comp("Stepper / Plus", mkStep("+", false));

// Toggle
function mkToggle(on){
  const c = figma.createComponent(); c.resize(52,32); c.cornerRadius=999; c.fills=[solid(on?C.RED:C.DISABLED)];
  const k = figma.createEllipse(); k.resize(24,24); k.fills=[solid(C.WHITE)];
  k.effects=[{type:"DROP_SHADOW",color:{r:0,g:0,b:0,a:0.15},offset:{x:0,y:1},radius:2,visible:true,blendMode:"NORMAL"}];
  c.appendChild(k); k.x = on? 24 : 4; k.y=4;
  return c;
}
made.toggleOn = comp("Toggle / On", mkToggle(true));
made.toggleOff = comp("Toggle / Off", mkToggle(false));

