function mkRadio(on){
  const c = figma.createComponent(); c.resize(24,24); c.cornerRadius=999;
  c.fills=[solid(C.WHITE)]; c.strokes=[solid(on?C.RED:C.DISABLED)]; c.strokeWeight=2;
  if(on){ const d=figma.createEllipse(); d.resize(12,12); d.fills=[solid(C.RED)]; c.appendChild(d); d.x=6;d.y=6; }
