const out = [];
for (const id of ids){
  const n = await figma.getNodeByIdAsync(id);
  if(!n){ out.push(id+" MISSING"); continue; }
  let info = id+" | "+n.name+" | "+n.type+" | "+Math.round(n.width)+"x"+Math.round(n.height);
  if(n.fills && n.fills.length && n.fills[0].type==="IMAGE") info += " | IMG scaleMode="+n.fills[0].scaleMode;
  else if(n.fills && n.fills.length) info += " | fill="+JSON.stringify(n.fills[0].type);
  if(n.type==="COMPONENT"||n.type==="INSTANCE"){
    const kids=[];
    const walk=(x,d)=>{ if(d>3)return; for(const c of x.children||[]){ kids.push(" ".repeat(d)+c.name+":"+c.type+(c.fills&&c.fills[0]&&c.fills[0].type==="SOLID"?"#"+Object.values(c.fills[0].color).map(v=>Math.round(v*255).toString(16).padStart(2,"0")).join(""):"")); walk(c,d+1);} };
    walk(n,0);
    info += "\n  "+kids.join("\n  ");
  }
  out.push(info);
}
return out.join("\n");

