function dump(n,d){
  let s = " ".repeat(d)+n.name+" "+n.type;
  if(n.cornerRadius!==undefined&&n.cornerRadius!==0&&n.cornerRadius!==figma.mixed) s+=" r="+n.cornerRadius;
  if(n.fills&&n.fills[0]&&n.fills[0].type==="SOLID") s+=" fill="+JSON.stringify(n.fills[0].color)+" op="+(n.fills[0].opacity??1);
  if(n.type==="TEXT") s+=" chars="+JSON.stringify(n.characters)+" font="+n.fontName.family+"/"+n.fontName.style+" size="+n.fontSize;
  if(n.layoutMode&&n.layoutMode!=="NONE") s+=" layout="+n.layoutMode+" pad="+n.paddingLeft+"/"+n.paddingTop+" gap="+n.itemSpacing;
  if(n.effects&&n.effects.length) s+=" fx="+n.effects.map(e=>e.type).join(",");
  let out=[s];
  if(n.children) for(const c of n.children) out=out.concat(dump(c,d+1));
  return out;
}
