function recolor(node,color){
  const walk=n=>{
    try{ if(n.fills&&n.fills.length&&n.fills!==figma.mixed){const f=n.fills.map(p=>p.type==="SOLID"?solid(color):p);n.fills=f;} }catch(e){}
    try{ if(n.strokes&&n.strokes.length){n.strokes=n.strokes.map(p=>p.type==="SOLID"?solid(color):p);} }catch(e){}
    if(n.children)for(const c of n.children)walk(c);
  };
  walk(node);
}
async function icon(key,size,color){
  const comp=await G(ICON[key]);
  const inst=comp.createInstance();
  inst.resize(size,size);
  recolor(inst,color);
  return inst;
}
