const page = figma.root.children.find(p=>p.name.startsWith("03"));
const out=[];
for(const fname of ["03_Product_Cheeseburger","07_Customize"]){
  const f=page.children.find(c=>c.name===fname);
  out.push("=== "+fname+" ===");
  const walk=(n,ind,d)=>{
    if(d>3)return;
    if(/btn|button|order/i.test(n.name)) out.push(ind+n.name+" ("+n.type+") reactions="+n.reactions.length);
    if(n.children)for(const ch of n.children)walk(ch,ind+"  ",d+1);
  };
  walk(f,"",0);
}
return out.join("\n");

const page = figma.root.children.find(p=>p.name.startsWith("03"));
const frames={};
for(const c of page.children) if(c.type==="FRAME"&&c.width===430&&c.height===932) frames[c.name]=c;
function find(root,pred){const res=[];const walk=n=>{if(pred(n))res.push(n);if(n.children)for(const ch of n.children)walk(ch);};walk(root);return res;}
function byName(root,name){const r=find(root,n=>n.name===name);return r[0]||null;}
const SMART={type:"SMART_ANIMATE",duration:0.3,easing:{type:"EASE_IN_AND_OUT"}};
function navAction(dst){return {type:"NODE",destinationId:dst.id,navigation:"NAVIGATE",transition:SMART};}

const errs=[];
const b3=byName(frames["03_Product_Cheeseburger"],"OrderNow");
if(b3){b3.reactions=[{trigger:{type:"ON_CLICK"},actions:[navAction(frames["07_Customize"])]}];}else errs.push("03 OrderNow");
const b7=byName(frames["07_Customize"],"OrderNow");
if(b7){b7.reactions=[{trigger:{type:"ON_CLICK"},actions:[navAction(frames["08_Payment"])]}];else errs.push("07 OrderNow");

// Final verification: count all reactions across all frames
const summary=[];
for(const [name,f] of Object.entries(frames)){
  let count=0;
  const walk=n=>{if(n.reactions&&n.reactions.length)count+=n.reactions.length;if(n.children)for(const ch of n.children)walk(ch);};
  walk(f);
  summary.push(name+": "+count+" reactions");
}
return (errs.length?"ERRORS: "+errs.join(", "):"OK")+"\n"+summary.join("\n");

