const page = figma.root.children.find(p=>p.name.startsWith("03"));
const out=[];
for(const c of page.children){
  if(c.type!=="FRAME"||c.width!==430||c.height!==932)continue;
  const names=[];const walk=n=>{names.push(n.name);if(n.children)for(const ch of n.children)walk(ch);};
  walk(c);
  const hasSB=names.includes("Status Bar"), hasHI=names.includes("Home Indicator");
  out.push(c.name+": StatusBar="+(hasSB?"Y":"N")+" HomeIndicator="+(hasHI?"Y":"N"));
}
